      transition: all 0.2s; z-index: 10000;
    }
    .skip-to-content:focus { top: 6px; opacity: 1; pointer-events: auto; }

    #viz-container {
      width: 1400px;
      height: 950px;
      margin: 0 auto;
      position: relative;
      background: var(--bg);
    }

    svg { display: block; }

    .tier-band {
      fill-opacity: 0.04;
    }
    .theme-light .tier-band {
      fill-opacity: 0.03;
    }

    .tier-label {
      font-size: 13px;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      fill: var(--text-secondary);
    }

    .node-rect {
      rx: 6;
      ry: 6;
      stroke-width: 1.5;
      transition: all 0.2s;
      cursor: pointer;
    }
