    }

    .node-text {
      font-size: 11px;
      font-weight: 500;
      fill: var(--text);
      pointer-events: none;
      text-anchor: middle;
      dominant-baseline: middle;
    }

    .node-type-icon {
      pointer-events: none;
    }

    .edge-path {
      fill: none;
      stroke-linecap: round;
      transition: stroke-width 0.2s, opacity 0.2s;
    }
    .edge-path:hover {
      stroke-width: 3;
      opacity: 1;
    }

    .edge-label-bg {
      rx: 3;
      ry: 3;
    }
    .edge-label {
      font-size: 9px;
      font-weight: 500;
      fill: var(--text-secondary);
      text-anchor: middle;
      dominant-baseline: middle;
      pointer-events: none;
    }

    .legend-item {
      cursor: default;
    }
    .legend-text {
      font-size: 11px;
      fill: var(--text-secondary);
    }

    .observability-band {
      fill-opacity: 0.03;
      stroke-dasharray: 4,4;
    }

    .hotspot-ring {
      fill: none;
      stroke-width: 2;
      stroke-dasharray: 3,2;
      opacity: 0.6;
      animation: pulse 2s ease-in-out infinite;
    }
    @keyframes pulse {
