      { source: "order-service", target: "inventory-service", connection_type: "sync", protocol: "gRPC", proxied: true },
      { source: "order-service", target: "kafka-mq", connection_type: "async", protocol: "Kafka", proxied: false },
      { source: "payment-service", target: "kafka-mq", connection_type: "async", protocol: "Kafka", proxied: false },
      { source: "kafka-mq", target: "notification-service", connection_type: "async", protocol: "Kafka", proxied: false },
