      { source: "kafka-mq", target: "recommendation-engine", connection_type: "async", protocol: "Kafka", proxied: false },
      { source: "product-catalog", target: "recommendation-engine", connection_type: "sync", protocol: "gRPC", proxied: true },
      { source: "product-catalog", target: "redis-cache", connection_type: "sync", protocol: "Redis", proxied: false },
      { source: "product-catalog", target: "postgres-replica", connection_type: "sync", protocol: "SQL", proxied: false },
      { source: "order-service", target: "postgres-primary", connection_type: "sync", protocol: "SQL", proxied: false },
      { source: "payment-service", target: "postgres-primary", connection_type: "sync", protocol: "SQL", proxied: false },
      { source: "inventory-service", target: "postgres-primary", connection_type: "sync", protocol: "SQL", proxied: false },
      { source: "user-profile", target: "mongodb", connection_type: "sync", protocol: "MongoDB", proxied: false },
      { source: "user-profile", target: "redis-cache", connection_type: "sync", protocol: "Redis", proxied: false },
      { source: "recommendation-engine", target: "mongodb", connection_type: "sync", protocol: "MongoDB", proxied: false },
      { source: "recommendation-engine", target: "redis-cache", connection_type: "sync", protocol: "Redis", proxied: false },
      { source: "search-service", target: "elasticsearch", connection_type: "sync", protocol: "REST", proxied: false },
      { source: "search-service", target: "redis-cache", connection_type: "sync", protocol: "Redis", proxied: false },
      { source: "notification-service", target: "mongodb", connection_type: "sync", protocol: "MongoDB", proxied: false },
      { source: "auth-service", target: "redis-cache", connection_type: "sync", protocol: "Redis", proxied: false },
      { source: "auth-service", target: "postgres-replica", connection_type: "sync", protocol: "SQL", proxied: false },
      { source: "rate-limiter", target: "redis-cache", connection_type: "sync", protocol: "Redis", proxied: false },
      { source: "postgres-primary", target: "postgres-replica", connection_type: "async", protocol: "Replication", proxied: false },
      { source: "istio-control", target: "api-gateway", connection_type: "sync", protocol: "xDS", proxied: false },
      { source: "istio-control", target: "auth-service", connection_type: "sync", protocol: "xDS", proxied: false },
      { source: "istio-control", target: "rate-limiter", connection_type: "sync", protocol: "xDS", proxied: false },
      { source: "istio-control", target: "product-catalog", connection_type: "sync", protocol: "xDS", proxied: false },
      { source: "istio-control", target: "order-service", connection_type: "sync", protocol: "xDS", proxied: false },
      { source: "istio-control", target: "payment-service", connection_type: "sync", protocol: "xDS", proxied: false },
      { source: "istio-control", target: "inventory-service", connection_type: "sync", protocol: "xDS", proxied: false },
      { source: "istio-control", target: "user-profile", connection_type: "sync", protocol: "xDS", proxied: false },
      { source: "istio-control", target: "recommendation-engine", connection_type: "sync", protocol: "xDS", proxied: false },
      { source: "istio-control", target: "notification-service", connection_type: "sync", protocol: "xDS", proxied: false },
      { source: "istio-control", target: "search-service", connection_type: "sync", protocol: "xDS", proxied: false },
      { source: "jaeger-tracing", target: "grafana", connection_type: "sync", protocol: "REST", proxied: false },
      { source: "prometheus", target: "grafana", connection_type: "sync", protocol: "PromQL", proxied: false },
      { source: "efk-logging", target: "grafana", connection_type: "sync", protocol: "REST", proxied: false }
    ];

    // Compute degrees
    var inDeg = {}, outDeg = {}, totalDeg = {};
    nodes.forEach(function(n) { inDeg[n.id] = 0; outDeg[n.id] = 0; totalDeg[n.id] = 0; });
    edges.forEach(function(e) {
      outDeg[e.source] = (outDeg[e.source] || 0) + 1;
      inDeg[e.target] = (inDeg[e.target] || 0) + 1;
    });
    nodes.forEach(function(n) { totalDeg[n.id] = (inDeg[n.id] || 0) + (outDeg[n.id] || 0); });

    // ========== LAYOUT ==========
    var W = 1400, H = 950;
    var margin = { top: 60, right: 40, bottom: 140, left: 40 };
    var innerW = W - margin.left - margin.right;
    var innerH = H - margin.top - margin.bottom;

    var tierHeights = { "Access": 0.22, "Business": 0.40, "Data": 0.22, "Observability": 0.16 };
    var tierOrder = ["Access", "Business", "Data", "Observability"];
    var tierColors = {
      "Access": "#3b82f6",
      "Business": "#10b981",
      "Data": "#f59e0b",
      "Observability": "#8b5cf6"
    };
    var tierBgColors = {
      "Access": "rgba(59,130,246,0.06)",
      "Business": "rgba(16,185,129,0.06)",
      "Data": "rgba(245,158,11,0.06)",
      "Observability": "rgba(139,92,246,0.06)"
    };

    var nodeTypeColors = {
      "service": "#3b82f6",
      "infrastructure": "#f59e0b",
      "observability": "#8b5cf6",
      "service_mesh_control": "#ec4899"
    };

    var nodeW = 110, nodeH = 40;

    // Position nodes by tier
    var tierNodes = {};
    tierOrder.forEach(function(t) { tierNodes[t] = nodes.filter(function(n) { return n.tier === t; }); });

    var yCursor = margin.top;
    var tierY = {};
    tierOrder.forEach(function(t) {
      var h = innerH * tierHeights[t];
      tierY[t] = { y: yCursor, h: h, mid: yCursor + h / 2 };
      yCursor += h;
    });

    // X positions per tier
    function distribute(nodesList, startX, endX) {
      var n = nodesList.length;
      var step = (endX - startX) / Math.max(n, 1);
      var offset = step / 2;
      nodesList.forEach(function(node, i) {
        node.x = startX + offset + i * step;
        node.y = tierY[node.tier].mid;
      });
    }

    distribute(tierNodes["Access"], margin.left + 40, margin.left + innerW - 40);
    distribute(tierNodes["Business"], margin.left + 20, margin.left + innerW - 20);
    distribute(tierNodes["Data"], margin.left + 40, margin.left + innerW - 40);
    // Observability on the right side
    var obsNodes = tierNodes["Observability"];
    var obsX = margin.left + innerW - 180;
    obsNodes.forEach(function(n, i) {
      n.x = obsX;
      n.y = tierY["Observability"].y + 30 + i * 50;
    });

    // Map edges to node objects
    var nodeMap = {};
    nodes.forEach(function(n) { nodeMap[n.id] = n; });
    edges.forEach(function(e) {
      e.sourceNode = nodeMap[e.source];
      e.targetNode = nodeMap[e.target];
    });

    // ========== RENDER ==========
    var svg = d3.select("#viz-container").append("svg")
      .attr("width", W).attr("height", H);

    var isDark = document.documentElement.classList.contains('theme-dark');
    var textColor = isDark ? '#EDEDED' : '#0f172a';
    var textSecondary = isDark ? '#888' : '#64748b';
    var borderColor = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.10)';
    var bgColor = isDark ? '#0A0A0A' : '#FAFAF9';

    // Background
    svg.append("rect").attr("width", W).attr("height", H).attr("fill", bgColor);

    // Title
    var titleG = svg.append("g").attr("class", "animate");
    titleG.append("text")
      .attr("x", W / 2).attr("y", 36)
      .attr("text-anchor", "middle")
      .attr("font-size", "22px").attr("font-weight", "700")
      .attr("fill", textColor).attr("letter-spacing", "-0.02em")
      .text("E-Commerce Platform Architecture — 3-Tier Topology with 12 Services");

    // Tier bands
    var bandG = svg.append("g");
    tierOrder.forEach(function(t) {
      if (t === "Observability") return;
      var ty = tierY[t];
      bandG.append("rect")
        .attr("x", margin.left).attr("y", ty.y)
        .attr("width", innerW).attr("height", ty.h)
        .attr("fill", tierBgColors[t])
        .attr("stroke", borderColor)
        .attr("stroke-width", 1)
        .attr("class", "tier-band");
      bandG.append("text")
        .attr("x", margin.left + 12).attr("y", ty.y + 20)
        .attr("class", "tier-label")
        .text(t + " Layer");
    });

    // Observability overlay band (right side)
    var obsY = tierY["Observability"];
    bandG.append("rect")
      .attr("x", margin.left + innerW - 220)
      .attr("y", obsY.y)
      .attr("width", 220).attr("height", obsY.h)
      .attr("fill", tierBgColors["Observability"])
      .attr("stroke", borderColor)
      .attr("stroke-width", 1)
      .attr("class", "observability-band");
    bandG.append("text")
      .attr("x", margin.left + innerW - 208)
      .attr("y", obsY.y + 18)
      .attr("class", "tier-label")
      .attr("fill", tierColors["Observability"])
      .text("Observability & Service Mesh");

    // Edge routing with curvature
    function edgePath(d) {
      var sx = d.sourceNode.x, sy = d.sourceNode.y;
      var tx = d.targetNode.x, ty = d.targetNode.y;
      var dx = tx - sx, dy = ty - sy;
      var dr = Math.sqrt(dx * dx + dy * dy);
      // If same tier, use more curve; if different tiers, straighter
      if (d.sourceNode.tier === d.targetNode.tier) {
        var midX = (sx + tx) / 2;
        var midY = (sy + ty) / 2 - 60;
        return "M" + sx + "," + sy + " Q" + midX + "," + midY + " " + tx + "," + ty;
      }
      var cpY = (sy + ty) / 2;
      return "M" + sx + "," + sy + " C" + sx + "," + cpY + " " + tx + "," + cpY + " " + tx + "," + ty;
    }

    // Draw edges (behind nodes)
    var edgeG = svg.append("g").attr("class", "animate delay-1");
    edges.forEach(function(e, i) {
      var g = edgeG.append("g").attr("class", "edge-group");
      var strokeColor;
      if (e.proxied) strokeColor = "#ec4899";
      else if (e.connection_type === "async") strokeColor = "#f59e0b";
      else strokeColor = isDark ? "rgba(255,255,255,0.25)" : "rgba(0,0,0,0.25)";

      var strokeWidth = e.proxied ? 2.5 : 1.5;
      var dash = e.connection_type === "async" ? "6,4" : "none";
      var opacity = e.sourceNode.tier === "Observability" || e.targetNode.tier === "Observability" ? 0.5 : 0.7;

      g.append("path")
        .attr("d", edgePath(e))
        .attr("stroke", strokeColor)
        .attr("stroke-width", strokeWidth)
        .attr("stroke-dasharray", dash)
        .attr("fill", "none")
        .attr("opacity", opacity)
        .attr("class", "edge-path");
    });

    // Draw nodes
    var nodeG = svg.append("g").attr("class", "animate delay-2");

    nodes.forEach(function(n) {
      var g = nodeG.append("g").attr("class", "node-group");
      var nx = n.x - nodeW / 2, ny = n.y - nodeH / 2;

      var fill, stroke;
      if (n.type === "service") {
        fill = isDark ? "rgba(59,130,246,0.12)" : "rgba(59,130,246,0.08)";
        stroke = "#3b82f6";
      } else if (n.type === "infrastructure") {
