        stroke = "#8b5cf6";
      } else if (n.type === "service_mesh_control") {
        fill = isDark ? "rgba(236,72,153,0.12)" : "rgba(236,72,153,0.08)";
        stroke = "#ec4899";
      }

      // Hotspot ring for high-degree nodes (>=5)
      if (totalDeg[n.id] >= 5) {
        g.append("circle")
          .attr("cx", n.x).attr("cy", n.y)
          .attr("r", 30)
          .attr("class", "hotspot-ring")
          .attr("stroke", "#f43f5e");
      }

      g.append("rect")
        .attr("x", nx).attr("y", ny)
        .attr("width", nodeW).attr("height", nodeH)
        .attr("fill", fill).attr("stroke", stroke)
        .attr("class", "node-rect");

