      if (label.length > 14) label = label.substring(0, 13) + "…";
      g.append("text")
        .attr("x", n.x).attr("y", n.y)
        .attr("class", "node-text")
        .text(label);

      // Connection count for hotspots
      if (totalDeg[n.id] >= 5) {
        g.append("text")
          .attr("x", n.x + nodeW / 2 + 6).attr("y", n.y - nodeH / 2 - 6)
          .attr("class", "conn-count")
          .text(totalDeg[n.id]);
      }
    });

    // Legend
    var legendG = svg.append("g").attr("class", "animate delay-3");
    var legendX = margin.left + 20;
