    .attr("width", nodeW).attr("height", nodeH)
    .attr("fill", fill).attr("stroke", stroke)
    .attr("class", "node-rect");

  if (n.service_mesh) {
    g.append("rect")
      .attr("x", nx + nodeW - 16).attr("y", ny - 5)
      .attr("width", 20).attr("height", 9)
      .attr("rx", 3).attr("fill", "#ec4899").attr("opacity", 0.85);
    g.append("text")
      .attr("x", nx + nodeW - 6).attr("y", ny - 1)
      .attr("class", "sidecar-badge")
      .text("S");
  }

  var label = n.label;
  if (label.length > 15) label = label.substring(0, 14) + "…";
  g.append("text")
    .attr("x", n.x).attr("y", n.y)
    .attr("class", "node-text")
    .text(label);

  if (totalDeg[n.id] >= 5) {
    g.append("text")
      .attr("x", n.x + nodeW / 2 + 8).attr("y", n.y - nodeH / 2 - 8)
      .attr("class", "conn-count")
      .text(totalDeg[n.id]);
  }
});

// Legend
var legendG = svg.append("g").attr("class", "animate delay-3");
var legendX = margin.left + 20;
var legendY = H - 105;
legendG.append("rect")
  .attr("x", legendX - 10).attr("y", legendY - 10)
  .attr("width", W - margin.left - margin.right + 20).attr("height", 95)
  .attr("fill", isDark ? "rgba(255,255,255,0.02)" : "rgba(0,0,0,0.02)")
  .attr("stroke", borderColor).attr("rx", 8);
legendG.append("text")
  .attr("x", legendX).attr("y", legendY + 8)
  .attr("font-size", "12px").attr("font-weight", "600")
  .attr("fill", textColor)
  .text("Legend");

var items = [
  { label: "Service (Access)", color: "#3b82f6", x: 0 },
  { label: "Service (Business)", color: "#10b981", x: 140 },
  { label: "Cache", color: "#f59e0b", x: 300 },
  { label: "Database", color: "#059669", x: 380 },
  { label: "Message Queue", color: "#ec4899", x: 480 },
  { label: "Observability", color: "#8b5cf6", x: 620 },
  { label: "Service Mesh", color: "#ec4899", x: 760 },
  { label: "Sync Call", color: isDark ? "rgba(255,255,255,0.5)" : "rgba(0,0,0,0.5)", x: 900, isLine: true },
  { label: "Async Call", color: "#f59e0b", x: 1000, isLine: true, dash: "4,3" },
  { label: "Proxied (Sidecar)", color: "#ec4899", x: 1110, isLine: true },
  { label: "Hotspot (≥5 conns)", color: "#f43f5e", x: 1260, isRing: true }
];
items.forEach(function(item) {
  var ix = legendX + item.x;
  var iy = legendY + 34;
  if (item.isLine) {
    legendG.append("line")
      .attr("x1", ix).attr("y1", iy).attr("x2", ix + 20).attr("y2", iy)
      .attr("stroke", item.color).attr("stroke-width", 2)
      .attr("stroke-dasharray", item.dash || "none");
  } else if (item.isRing) {
    legendG.append("circle")
      .attr("cx", ix + 10).attr("cy", iy).attr("r", 8)
      .attr("fill", "none").attr("stroke", item.color).attr("stroke-width", 1.5)
      .attr("stroke-dasharray", "3,2");
  } else {
    legendG.append("rect")
      .attr("x", ix).attr("y", iy - 6).attr("width", 12).attr("height", 12)
      .attr("rx", 3).attr("fill", item.color).attr("opacity", 0.7);
  }
  legendG.append("text")
    .attr("x", ix + (item.isLine ? 26 : 18)).attr("y", iy + 1)
    .attr("class", "legend-text")
    .text(item.label);
});

// Bottom annotation
svg.append("text")
  .attr("x", W / 2).attr("y", H - 18)
  .attr("text-anchor", "middle")
  .attr("font-size", "10px").attr("fill", textSecondary)
  .text("44 connections total  ·  Solid = sync  ·  Dashed = async  ·  Pink = sidecar-proxied  ·  Red dashed ring = dependency hotspot");

function onThemeChange() {
  location.reload();
}
</script>
</body>
</html>
